pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amountA, uint256 amountB, address actorA, address actorB) public {
        vm.assume(actorA != address(0) && actorB != address(0) && actorA != actorB);
        vm.assume(amountA > 0 && amountB > 0 && amountA <= type(uint256).max - amountB);
        // Reentrant attacker that calls withdrawBalance again during withdrawBalance
        Attacker attacker = new Attacker(c);
        address attackerAddr = address(attacker);

        vm.deal(actorA, amountA);
        vm.prank(actorA);
        c.addToBalance{value: amountA}();

        vm.deal(attackerAddr, amountB);
        vm.prank(attackerAddr);
        c.addToBalance{value: amountB}();

