pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to avoid overflow in the attacker contract
        amount = bound(amount, 1, type(uint128).max);

        // Deploy a reentrant attacker that calls addToBalance on withdraw
        Attacker attacker = new Attacker();
        vm.deal(address(attacker), amount);

        // Attacker deposits funds
        vm.prank(address(attacker));
        c.addToBalance{value: amount}();

        // Now the attacker withdraws, triggering the reentrant callback
        uint256 balanceBefore = c.getBalance(address(attacker));
        vm.prank(address(attacker));
        c.withdrawBalance();
        uint256 balanceAfter = c.getBalance(address(attacker));

        // In the reference contract, the lock prevents reentrancy, so after withdrawal the attacker's balance is 0.
        // In the buggy contract, the attacker can re-enter addToBalance during the ETH transfer, depositing the drained funds again,
        // resulting in a non-zero balance after withdrawal.
        assertTrue(balanceAfter == 0);
    }
}

contract Attacker {
    C public target;
    uint256 public attackValue;

    function setTarget(address _target) external {
        target = C(_target);
    }

    receive() external payable {
        // Re-enter addToBalance with the received ETH, but only once to avoid infinite loop
        if (address(target).balance >= attackValue && attackValue > 0) {
            uint256 val = attackValue;
            attackValue = 0;
            target.addToBalance{value: val}();
        }
    }

    function startAttack(address _target) external payable {
        target = C(_target);
        attackValue = msg.value;
        target.addToBalance{value: msg.value}();
        target.withdrawBalance();
    }
}

