import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 initialBalance, uint256 sendValue) public {
        vm.assume(sender != address(0));
        vm.deal(sender, sendValue);
        // pre-load a non-zero initial balance for sender
        // We need to call addToBalance with value=initialBalance to set a starting balance
        // but we can only set via addToBalance. We do a first deposit.
        vm.deal(sender, initialBalance + sendValue);
        vm.prank(sender);
        c.addToBalance{value: initialBalance}();

        uint256 balanceBefore = c.getBalance(sender);
        // Ensure initial deposit succeeded
        vm.prank(sender);
        c.addToBalance{value: sendValue}();
        uint256 balanceAfter = c.getBalance(sender);
        assertTrue(balanceAfter == balanceBefore + sendValue);
        // The universal property: balanceAfter = balanceBefore (from getBalance) + sendValue.
        // In the bug, addToBalance adds 0, so balanceAfter == balanceBefore, breaking equality.
    }
}

