import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit, address other) public {
        vm.assume(other != address(0) && other != address(c));
        deposit = bound(deposit, 1, type(uint256).max / 2);

        // Deploy re-entrant attacker helper
        ReentrantExploiter exploiter = new ReentrantExploiter(c);
        address attacker = address(exploiter);

        // Fund the attacker and make it deposit once; it will re-enter during addToBalance
        vm.deal(attacker, deposit);
        vm.prank(attacker);
        exploiter.attack{value: deposit}();

        // After the attack, the invariant: contract balance == sum of userBalance of attacker + other
        // The reference contract enforces this (sum never exceeds balance).
        // The buggy version allows reentrant double-counting, so userBalance[attacker] grows beyond deposit,
        // making sum > balance.
        uint256 sumBalances = c.getBalance(attacker) + c.getBalance(other);
        assertTrue(sumBalances <= address(c).balance);
    }
}

contract ReentrantExploiter {
    C target;
    bool private reenterGuard;
    constructor(C _target) { target = _target; }
    function attack() external payable {
        require(msg.value > 0);
        target.addToBalance{value: msg.value}();
        // withdraw reentrantly triggers again during withdrawBalance callback
        target.withdrawBalance();
    }
    receive() external payable {
        if (!reenterGuard) {
            reenterGuard = true;
            // re-enter addToBalance with the same Ether just received
            target.addToBalance{value: msg.value}();
            reenterGuard = false;
        }
    }
}

